nextflow_process {

    name "Test Process SNAKEMAKE"
    script "../main.nf"
    process "SNAKEMAKE"
    tag "snakemake"
    tag "modules"
    tag "modules_nfcore"

    test("Should run without failures") {

        when {
            process {
                """
        // Input file
        input[0] = [
            [ id: 'input'],
            []
        ]
// Snakefile
    channel.of('''
rule all:
    input: "hello.txt"

rule hello_world:
    output: "hello.txt"
    shell: "echo Hello World > hello.txt"

'''
        )
        .collectFile(name: 'Snakefile')
        .map { file ->
            [
                [id: 'Snakefile'],
                file
            ]}
        .set{ snakefile }

        input[1] = snakefile
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(
                    process.out.outputs,
                    process.out.findAll { key, val -> key.startsWith("versions") }
                ).match() }
            )
        }
    }
    test("Should run without failures - stub") {
        options "-stub"
        when {
            process {
                """
        // Input file
        input[0] = [
            [ id: 'input'],
            []
        ]
// Snakefile
    channel.of('''
rule all:
    input: "hello.txt"

rule hello_world:
    output: "hello.txt"
    shell: "echo Hello World > hello.txt"

'''
        )
        .collectFile(name: 'Snakefile')
        .map { file ->
            [
                [id: 'Snakefile'],
                file
            ]}
        .set{ snakefile }

        input[1] = snakefile
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(
                    process.out.outputs,
                    process.out.findAll { key, val -> key.startsWith("versions") }
                ).match() }
            )
        }
    }
}

